function journey(){
 if(transformationPreview)return transformationPreviewView()
 const weights=(state.weighIns||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)),latest=weights.at(-1),b=latest&&state.heightCm?bmi(latest.weightKg,state.heightCm):null,recent=(state.activities||[]).slice(-3).reverse(),gps=(state.activities||[]).filter(a=>a.routePoints?.length>1),photos=progressPhotos||[]
 return progress()+`
 <section class="journey-sections">
  <details class="journey-panel"><summary><span><p class="eyebrow">BODY & WELLBEING</p><strong>${latest?latest.weightKg.toFixed(1)+' kg':'No weigh-in yet'}</strong><small>${b?'BMI '+b.toFixed(1)+' · ':''}${weights.length?weights.length+' weigh-in'+(weights.length===1?'':'s'):'Optional tracking'}</small></span></summary><div class="journey-panel-body">${body()}</div></details>
  <details class="journey-panel"><summary><span><p class="eyebrow">YOUR TRANSFORMATION</p><strong>Progress photos</strong><small>${photos.length} private photo${photos.length===1?'':'s'} · Take, upload or build a before/after</small></span></summary><div class="journey-panel-body">${progressPhotosView()+transformationComposer()}</div></details>
  <details class="journey-panel"><summary><span><p class="eyebrow">ACTIVITY JOURNAL</p><strong>${recent.length?'Recent movement':'Nothing logged yet'}</strong><small>${(state.activities||[]).length} activit${(state.activities||[]).length===1?'y':'ies'} · ${gps.length} saved route${gps.length===1?'':'s'}</small></span></summary><div class="journey-panel-body">${activityHistory()+routeHistory()}</div></details>
  <section class="history journey-recent"><div class="compact-heading"><div><p class="eyebrow">LATEST ACTIVITY</p><h3>Activity journal</h3></div></div>${recent.length?recent.map(a=>`<div><span><strong>${escapeHtml(a.name)}</strong><small>${a.date}${a.distanceKm!=null?' · '+a.distanceKm+' km':''}</small></span><strong>${a.minutes} min</strong></div>`).join(''):'<p class="hint">Your movement will appear here as you log it.</p>'}<button id="open-activity-journal" class="text-button">View all activity →</button></section>
  <section class="history journey-direction"><p class="eyebrow">MY DIRECTION</p><h3>${escapeHtml(state.direction||'Set your direction when you are ready.')}</h3><button data-view="setup" class="text-button">${state.direction?'Update my direction →':'Set my direction →'}</button></section>
 </section>`}

function community(){
 const commentsBy=communityComments.reduce((m,x)=>((m[x.post_id]??=[]).push(x),m),{})
 return head('COMMUNITY','Transform together.','Share what you choose. Nothing from your private journey is posted here automatically.')+`
 <section class="community-compose form"><h3>Share an update</h3><textarea id="community-post-body" maxlength="3000" rows="4" placeholder="What would you like the Transform community to know?"></textarea><div class="community-compose-foot"><small>Only what you type here is shared.</small><button id="community-post">Post update</button></div>${communitySettings.moderated_posts?'<p class="hint">Moderation is on. New posts are reviewed before appearing to everyone.</p>':''}</section>
 ${moderatorNotices.filter(n=>!n.read_at).map(n=>'<section class="moderator-notice"><p class="eyebrow">PRIVATE NOTE FROM THE TRANSFORM TEAM</p><p>'+escapeHtml(n.message)+'</p></section>').join('')}
 <section class="community-feed">${communityFeed.length?communityFeed.map(p=>`<article class="community-post ${p.is_announcement?'announcement':''}"><div class="community-post-head"><div><strong>${escapeHtml(p.display_name)}</strong><small>${new Date(p.created_at).toLocaleDateString()}</small></div>${p.is_announcement?'<span class="community-badge">Announcement</span>':p.status==='pending'?'<span class="community-badge pending">Awaiting review</span>':''}</div><p>${escapeHtml(p.body).replace(/\n/g,'<br>')}</p>${communitySettings.comments_enabled&&!p.comments_closed&&p.status==='published'?'<div class="community-comments">'+(commentsBy[p.id]||[]).filter(x=>!x.is_hidden).map(x=>'<p><strong>'+escapeHtml(x.display_name||'Transform member')+'</strong> '+escapeHtml(x.body)+'</p>').join('')+'<div class="comment-compose"><input data-comment-input="'+p.id+'" maxlength="1000" placeholder="Add a comment…"><button data-comment-post="'+p.id+'">Comment</button></div></div>':p.comments_closed?'<small class="hint">Comments are closed on this post.</small>':''}</article>`).join(''):'<section class="history"><h3>The conversation starts here.</h3><p class="hint">Share an update when you are ready. Your private Transform data stays private.</p></section>'}</section>`
}
