 document.querySelector('#share-transformation')?.addEventListener('click',shareTransformation);document.querySelector('#close-transformation')?.addEventListener('click',()=>{transformationPreview=null;render()});document.querySelector('#preview-transformation')?.addEventListener('click',()=>{if(transformationSelection.length!==2)return;const photos=transformationSelection.map(id=>progressPhotos.find(p=>p.id===id)).filter(Boolean).sort((a,b)=>a.photo_date.localeCompare(b.photo_date));if(photos.length!==2)return;transformationPreview={photos,stats:selectedTransformationStats()};render();scrollTo(0,0)});document.querySelectorAll('[data-transform-photo]').forEach(b=>b.onclick=()=>{const p=progressPhotos[+b.dataset.transformPhoto];if(!p)return;if(transformationSelection.includes(p.id))transformationSelection=transformationSelection.filter(x=>x!==p.id);else{if(transformationSelection.length>=2)transformationSelection.shift();transformationSelection.push(p.id)}render()});const uploadProgressPhoto=async input=>{const pf=input;if(!pf)return;const file=pf.files?.[0];if(!file||!session)return;if(!file.type?.startsWith('image/')){syncMessage='Please choose an image file.';render();return}if(file.size>10*1024*1024){syncMessage='That photo is larger than the 10 MB upload limit. Choose a smaller image.';render();return}const kind=document.querySelector('#progress-photo-kind')?.value||'progress';const latest=(state.weighIns||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).at(-1);syncMessage='Saving your private progress photo…';render();try{const r=await addProgressPhoto(session.user.id,file,{kind,weightKg:latest?.weightKg||null});if(r.error){syncMessage='Your photo could not be saved. Your existing progress photos are unchanged.'}else{progressPhotos.push(r.data);syncMessage='Progress photo saved privately.'}}catch(e){console.warn('Progress photo upload failed',e);syncMessage='Your photo could not be saved. Check your connection and try again.'}render()};const pf=document.qu